examples.template:
Box {
    MonarchIconButton(label = "Account menu for " + {{user.name}}, onClick = { open = true }) {
        MonarchAvatar(image = null, name = {{user.name}}, size = MonarchAvatarSize.Sm, decorative = true)
    }
    MonarchMenu(expanded = open, onDismissRequest = { open = false }) {
        Column(
            modifier = Modifier
                .padding(horizontal = MonarchTheme.spacing.space3, vertical = MonarchTheme.spacing.space2)
                .semantics(mergeDescendants = true) {},
        ) {
            MonarchText(text = {{user.name}}, style = MonarchTextStyle.BodyStrong)
            MonarchText(text = {{user.email}}, style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
        }
        MonarchMenuDivider()
        MonarchMenuItem(
            text = "Profile",
            onClick = { open = false },
            leadingIcon = { MonarchIcon(SampleIcons.Person, contentDescription = null) },
        )
        MonarchMenuItem(
            text = "Settings",
            onClick = { open = false },
            leadingIcon = { MonarchIcon(SampleIcons.Settings, contentDescription = null) },
        )
        MonarchMenuDivider()
        MonarchMenuLabel(text = "Switch workspace")
        workspaces.forEach { (id, name) ->
            MonarchMenuItem(
                text = name,
                onClick = {
                    workspace = id
                    open = false
                },
                selected = id == workspace,
                leadingIcon = { MonarchAvatar(image = null, name = name, size = MonarchAvatarSize.Xs, decorative = true) },
            )
        }
        MonarchMenuDivider()
        MonarchMenuLabel(text = "Theme")
        listOf(MonarchScheme.Light to "Light", MonarchScheme.Dark to "Dark", MonarchScheme.System to "System").forEach { (option, label) ->
            MonarchMenuItem(text = label, onClick = { scheme = option }, selected = scheme == option)
        }
        MonarchMenuDivider()
        MonarchMenuItem(text = {{extraItem}}, onClick = { open = false })
        MonarchMenuDivider()
        MonarchMenuItem(
            text = "Sign out",
            onClick = { open = false },
            leadingIcon = { MonarchIcon(SampleIcons.Logout, contentDescription = null) },
        )
    }
}

