MonarchIconButton(label = "Account menu for Ada Lovelace", onClick = { open = true }) {
    MonarchAvatar(image = null, name = "Ada Lovelace", size = MonarchAvatarSize.Sm, decorative = true)
}
if (open) {
    MonarchBottomSheet(onDismissRequest = { open = false }) {
        Column(
            modifier = Modifier.verticalScroll(rememberScrollState()),
            verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
        ) {
            Row(
                horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                MonarchAvatar(image = null, name = "Ada Lovelace", size = MonarchAvatarSize.Lg, decorative = true)
                Column {
                    MonarchText(text = "Ada Lovelace", style = MonarchTextStyle.Heading)
                    MonarchText(text = "ada@example.com", color = MonarchTheme.colors.textMuted)
                }
            }
            MonarchButton(text = "Profile", onClick = { open = false }, modifier = Modifier.fillMaxWidth())
            MonarchButton(text = "Settings", onClick = { open = false }, modifier = Modifier.fillMaxWidth())
            MonarchThemeToggle(scheme = scheme, onSchemeChange = { scheme = it })
            MonarchButton(
                text = "Sign out",
                onClick = { open = false },
                modifier = Modifier.fillMaxWidth(),
                variant = MonarchButtonVariant.Danger,
            )
        }
    }
}
